},"trait_boost":null,"granted_trait_set":null}},{"tid":201980100,"trait_id":201980102,"trait":{"id":201980102,"trait_type":46,"trait_value":6,"desc":"搭乘单位含有「机动战士高达 闪光之凯萨卫」系列时，\n自身MP提升6\n自身受到的损伤减轻15%","action_timing":0,"tlimit":0,"active_condition_set_id":1000401,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":21,"trait_boost_condition_set_id":0,"active_condition":{"id":1000401,"trait_condition_set_id":1000401,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"1500","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":1500,"world_id":0,"name":"机动战士高达 闪光之凯萨卫","desc":"第二次新自护战争（马沙叛乱）后过了12年。\nU.C.0105──地球联邦政府的腐败加速了地球环境的污染，甚至还施行非人道的「猎人头」政策，强制将平民押送至宇宙。\n面对如此暴政，反地球联邦政府运动「马法狄」兴起，以暗杀联邦政府高官这般激烈的手段展开抵抗。\n领导人名为「马法狄‧纳比尤‧艾琳」。其真实身分为曾参与过一年战争的联邦军上校布拉度‧诺亚之子「凯萨卫」。\n身为继承了阿宝‧尼尔与马沙‧阿兹纳布的理念、理想以及遗志的战士，凯萨卫本想亲手开拓未来，但与联邦军上校坚尼斯‧斯莱格、神秘美少女琪琪‧安达露西亚的邂逅，彻底改变了他的命运。","icon":"series_1500","sort":325,"schedule_id":2511409901,"scenario_stage_series_id":1500,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"h